=Analyze this lead using the supplied data:

Full Name: {{ $('Normalize Lead Data').item.json.fullName }}
Job Title: {{ $('Normalize Lead Data').item.json.jobTitle }}
Company: {{ $('Normalize Lead Data').item.json.company }}
Website: {{ $('Normalize Lead Data').item.json.website }}
Email: {{ $('Normalize Lead Data').item.json.email }}
Country: {{ $('Normalize Lead Data').item.json.country }}
Message: {{ $('Normalize Lead Data').item.json.message }}
Meeting Requested: {{ $('Normalize Lead Data').item.json.meetingRequested }}
Lead Source: {{ $('Normalize Lead Data').item.json.source }}

Base your analysis primarily on explicit evidence in the lead's message, job title, company information, and meeting request.

A direct request to schedule a demo or discuss implementation is a strong buying signal and must materially increase lead score and purchase intent.

Do not treat missing company-size or industry information as evidence of low intent. If information cannot be determined reliably, state "Unknown" rather than inventing it.

Return the JSON structure required by the system instructions.

parameters.jsCode:
const item = $input.first();

// Extract OpenAI raw response
let rawText = '';
try {
  rawText = item.json.choices[0].message.content;
} catch (e) {
  rawText = '';
}

// Strip markdown fences and parse
let parsed;
try {
  const cleaned = rawText
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {};
}

// Allowed value sets
const validTemps = ['Cold', 'Warm', 'Hot'];
const validIntents = ['Browsing', 'Researching', 'Evaluating', 'Ready to Buy'];
const validQual = ['Disqualified', 'Needs Nurturing', 'Qualified', 'Sales Ready'];
const validSizes = ['1-10', '11-50', '51-200', '201-1000', '1000+'];
const validBizTypes = ['B2B', 'B2C', 'Enterprise', 'Startup', 'SMB', 'Agency'];
const validDealValues = ['<$5K', '$5K-$25K', '$25K-$100K', '$100K+'];
const validActions = ['Schedule Demo', 'Send Proposal', 'Discovery Call', 'Nurture Sequence', 'Disqualify'];

// Clamp score
const rawScore = parseInt(parsed.leadScore, 10);
const leadScore = isNaN(rawScore) ? 50 : Math.min(100, Math.max(0, rawScore));

// Derive temperature from score if AI value is invalid
function deriveTemp(score) {
  if (score >= 70) return 'Hot';
  if (score >= 40) return 'Warm';
  return 'Cold';
}

const temperature = validTemps.includes(parsed.temperature)
  ? parsed.temperature
  : deriveTemp(leadScore);

// Derive qualification from score if invalid
function deriveQual(score) {
  if (score >= 80) return 'Sales Ready';
  if (score >= 60) return 'Qualified';
  if (score >= 30) return 'Needs Nurturing';
  return 'Disqualified';
}

const result = {
  leadScore,
  temperature,
  intent: validIntents.includes(parsed.intent) ? parsed.intent : 'Researching',
  qualificationStatus: validQual.includes(parsed.qualificationStatus) ? parsed.qualificationStatus : deriveQual(leadScore),
  industry: (typeof parsed.industry === 'string' && parsed.industry.length > 0) ? parsed.industry : 'Unknown',
  companySize: validSizes.includes(parsed.companySize) ? parsed.companySize : '11-50',
  businessType: validBizTypes.includes(parsed.businessType) ? parsed.businessType : 'B2B',
  estimatedDealValue: validDealValues.includes(parsed.estimatedDealValue) ? parsed.estimatedDealValue : '$5K-$25K',
  companySummary: (typeof parsed.companySummary === 'string' && parsed.companySummary.length > 10) ? parsed.companySummary : 'Company analysis unavailable. Manual research recommended.',
  buyingSignals: (typeof parsed.buyingSignals === 'string' && parsed.buyingSignals.length > 5) ? parsed.buyingSignals : 'No clear buying signals detected.',
  potentialObjections: (typeof parsed.potentialObjections === 'string' && parsed.potentialObjections.length > 5) ? parsed.potentialObjections : 'Objections could not be predicted from available data.',
  recommendedAction: validActions.includes(parsed.recommendedAction) ? parsed.recommendedAction : 'Nurture Sequence',
  proposalAngle: (typeof parsed.proposalAngle === 'string' && parsed.proposalAngle.length > 5) ? parsed.proposalAngle : 'Focus on ROI and operational efficiency gains.',
  personalizedOpener: (typeof parsed.personalizedOpener === 'string' && parsed.personalizedOpener.length > 5) ? parsed.personalizedOpener : 'Thank you for reaching out — we would love to learn more about your needs.'
};

return [{ json: result }];

