const item = $input.first();

let rawText = '';
try {
  rawText = item.json.choices[0].message.content;
} catch (e) {
  rawText = '';
}

let parsed;
try {
  const cleaned = rawText
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {};
}

const leadName = $('Normalize Lead Data').item.json.fullName || 'there';
const company = $('Normalize Lead Data').item.json.company || 'your company';
const action = $('Parse & Validate AI Output').item.json.recommendedAction || 'Discovery Call';

const subject = (typeof parsed.subject === 'string' && parsed.subject.length > 3)
  ? parsed.subject
  : `Quick question about ${company}'s automation goals`;

const body = (typeof parsed.body === 'string' && parsed.body.length > 20)
  ? parsed.body
  : `Hi ${leadName},\n\nThank you for reaching out. Based on your message, I believe we can help ${company} achieve significant efficiency gains through intelligent automation.\n\nWould you be open to a quick 20-minute call to explore this further?\n\nBest regards,\n[Your Name]\nAI Automation Specialist`;

return [{ json: { emailSubject: subject, emailBody: body } }];

